const uyghurMedicineArticles = [
  {
    title: 'پىننە گۈلقەنتىنىڭ مېڭە ۋە ئاشقازاننى كۈچەيتىش رولى',
    category: 'خام دورىلار',
    sourceName: 'خەلقئارا ئۇيغۇر تىبابەت تەتقىقات تورى',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'پىننە گۈلقەنتى ئۇيغۇر تىبابىتىدە مىڭ يىلدىن بېرى ئىشلىتىلىپ كېلىۋاتقان ئەڭ ئەتىۋارلىق دورىلارنىڭ بىرى. تەبىئىتى ئىككىنچى دەرىجىدە قۇرۇق ئىسسىق بولۇپ، ئاشقازاننىڭ ھەزىم قىلىش ئىقتىدارىنى ئاشۇرىدۇ، كۆڭۈل ئېلىشىش ۋە ئاشقازان سوغۇقىنى يوقىتىدۇ. نېرۋىنى تىنچلاندۇرۇپ، ئۇيقۇسىزلىق ۋە مېڭە چارچاشقا پايدىلىق.',
    imageUrl: safeHerbalImages[0]
  },
  {
    title: 'كۈزلۈك ساقلىقنى ساقلاشتا مىزاج تەڭشەشنىڭ ئەھمىيىتى',
    category: 'ساقلىقنى ساقلاش',
    sourceName: 'ئۇيغۇر مىجەز تەڭشەش ۋە ساغلاملىق مەركىزى',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'ئۇيغۇر تىبابىتىدە پەسىل ئالمىشىش مەزگىلىدە بەدەن خىلىتلىرىنىڭ تەڭپۇڭلۇقىنى ساقلاش ئىنتايىن مۇھىم. كۈز كىرگەندە قۇرۇقلۇق ۋە سوغۇقلۇق ئاشىدىغان بولغاچقا، گۈلقەنت، تىرىياق، چىلان ۋە قۇرۇق ئۈزۈم مۇرابباسى ئىستېمال قىلىش بەدەن ھۆللۈكىنى ساقلاپ، يۆتەلنىڭ ئالدىنى ئالىدۇ.',
    imageUrl: safeHerbalImages[1]
  },
  {
    title: 'يۈرەك ۋە قان تومۇر كېسەللىكلىرىنىڭ ئالدىنى ئېلىش ئۇسۇللىرى',
    category: 'كېسەللىكنىڭ ئالدىنى ئېلىش',
    sourceName: 'ئىلى قاشتېشى كېسەللىكنىڭ ئالدىنى ئېلىش مەنبەسى',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'ئۇيغۇر تىبابەت نەزەرىيەسىگە كۆرە، قارا سەۋدە ۋە زەپەر يۈرەك مۇسكۇلىنىڭ خىزمىتىنى ياخشىلايدۇ. سەھەردە ئاچ قورساققا بىر چاي قوشۇق قارا سەۋدە مېيىنى سۈت ياكى سۇ بىلەن ئىچىپ بېرىش قان بېسىمىنى تەڭشەپ، قان ئۇيۇپ قېلىشنىڭ ئالدىنى ئالىدۇ.',
    imageUrl: safeHerbalImages[4]
  },
  {
    title: 'چۈچۈكبۇيا يىلتىزىنىڭ بەلغەم بوشىتىش ۋە باكتېرىيەگە قارشى شىپاسى',
    category: 'خام دورىلار',
    sourceName: 'ئۇيغۇر شىپالىق خام دورىلار قامۇسى',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'چۈچۈكبۇيا تەبىئىتى مۆتىدىل، تەمى تاتلىق شىپالىق ئۆسۈملۈك. كۆكرەك پەردە ياللۇغى، زىققا ۋە قۇرۇق يۆتەلگە ئىنتايىن پايدىلىق. چۈچۈكبۇيانى قايناقسۇدا دەملەپ ئىچكەندە گالدىكى قۇرۇقلۇقنى تۈگىتىدۇ.',
    imageUrl: safeHerbalImages[7]
  },
  {
    title: 'ئەتىگەنلىك ئوزۇقلىنىش ۋە بەدەن ئىممۇنىتېت كۈچىنى ئاشۇرۇش',
    category: 'ساقلىقنى ساقلاش',
    sourceName: 'تەبىئىي ئوزۇقلۇق ۋە تېبابەت بىلىملىرى',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'ئەتىگەنكى قورساقنى تاتلىق تەبىئىي چايلار ۋە قۇرۇق يەل-يېمىشلەر (ياڭاق، بادام، ئۆرۈك قېقى) بىلەن غىزالاندۇرۇش مېڭە ئېنېرگىيەسىنى ئاشۇرىدۇ. سوغۇق سۇ ۋە ياغلىق تاماقلاردىن پەرھىز تۇتۇش ھەزىمنى قوغدايدۇ.',
    imageUrl: safeHerbalImages[6]
  },
  {
    title: 'ئاشقازان ياللۇغىنىڭ تەبىئىي ئالدىنى ئېلىش چارىلىرى',
    category: 'كېسەللىكنىڭ ئالدىنى ئېلىش',
    sourceName: 'قەشقەر تىبابىتى ۋە قەدىمكى رېتسىپلار',
    sourceUrl: 'https://teklimakan.vercel.app',
    content: 'ئاشقازان كېسەللىكلىرىنىڭ ئالدىنى ئېلىشتا تاماقنى قەرەللىك يېيىش، غىزانى ياخشى چايناش ۋە زەرچىۋە (كۇركۇما) قوشۇلغان يېمەكلىكلەرنى ئىستېمال قىلىش كېرەك. زەرچىۋە ئاشقازان شىللىق پەردىسىنى قوغدايدۇ.',
    imageUrl: safeHerbalImages[2]
  }
];

const index = Math.floor(Date.now() / (12 * 60 * 60 * 1000)) % uyghurMedicineArticles.length;
const chosen = uyghurMedicineArticles[index] || uyghurMedicineArticles[0];

return [{
  json: {
    rawTitle: chosen.title,
    rawContent: chosen.content,
    rawCategory: chosen.category,
    sourceName: chosen.sourceName,
    sourceUrl: chosen.sourceUrl,
    imageUrl: chosen.imageUrl,
    sourcesList: sources
  }
}];

const item = $input.first().json;

const bannedKeywords = [
  'ناخشا', 'مۇزىكا', 'كىنو', 'تىياتىر', 'چولپان', 'مودېل', 'ئارتىس', 'ئارتىست',
  'مودىل', 'ئۇسسۇل', 'داڭلىق چولپان', 'فىلىم', 'song', 'music', 'movie', 'actor', 'model'
];

const textToCheck = (item.rawTitle + ' ' + item.rawContent).toLowerCase();
for (const bad of bannedKeywords) {
  if (textToCheck.includes(bad)) {
    return [];
  }
}

const safeHerbalBackup = [
  'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1000&q=80',
  'https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?auto=format&fit=crop&w=1000&q=80',
  'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=1000&q=80',
  'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?auto=format&fit=crop&w=1000&q=80'
];

let finalImg = item.imageUrl;
if (!finalImg || finalImg.includes('person') || finalImg.includes('face') || finalImg.includes('girl') || finalImg.includes('human')) {
  finalImg = safeHerbalBackup[Math.floor(Math.random() * safeHerbalBackup.length)];
}

return [{
  json: {
    ...item,
    verifiedImageUrl: finalImg,
    isFilterPassed: true
  }
}];

